 fn relay_quote(&self,kind:RelayKind,body:usize)->Result<(RetirementDemand,u64,RetirementDemand,u64),ValueError>{if let Some(route)=self.relay_route{if route.kind!=kind||route.body!=body{return Err(invalid())}return Ok((route.demand,route.work,route.child,route.child_work))}let(child,child_work)=match kind{RelayKind::Backing=>(self.backing.demands::<I,T,C>(&self.child,&self.retired_header,body)?,self.backing.work_demand::<I,T,C>(&self.child,&self.retired_header,body)?),RelayKind::Capture=>(R::capture_demand()?,R::capture_work_demand(&self.slots,&self.raw)?),RelayKind::Take=>(R::take_demand(&self.slots)?,R::take_work_demand(&self.slots,&self.output)?)};let demand=nested(child,Self::relay_prefix())?;Ok((demand,child_work.checked_add(1).ok_or_else(invalid)?,child,child_work))}
