 fn relay_map<'r>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{if self.relay_route.is_some()||self.relay.is_none(){return Err(invalid())}let demand=Self::relay_map_demand();if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"shared reply transfer exceeded its original Work").into())))}let result=self.relay.take().expect("resident reply selected");let progress=receipt(demand);Ok(reply.complete(match result{Ok(_)=>Ok(RetainedCloneStep::Progress(progress)),Err(error)=>{let mut primary:OriginalReceivingPrimary=error.into();primary.progress=progress;Err(primary)}}))}
